INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginne ich hier ohne Anforderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen festlegen ist erster Schritt"}, {"text": "Ja", "correct": false, "because": "Linearer Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst in diesem Prozess?', 3, '[{"text": "Anforderungen festlegen", "correct": true, "because": "Grundlage des Projekts"}, {"text": "System entwerfen", "correct": false, "because": "Folgt Anforderungen"}, {"text": "Tests durchführen", "correct": false, "because": "Später im Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu diesem Ablauf?', 5, '[{"text": "Code implementieren", "correct": true, "because": "Entwicklung umsetzen"}, {"text": "Produkt warten", "correct": true, "because": "Langfristige Pflege"}, {"text": "Iterative Zyklen", "correct": false, "because": "Linearer Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tests kommen nach der Implementierung. b) Entwurf ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entwurf essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich in diesem Ablauf?', 4, '[{"text": "Anforderungen festlegen", "correct": false, "because": "Basis des Prozesses"}, {"text": "Tests durchführen", "correct": false, "because": "Qualität prüfen"}, {"text": "Flexible Änderungen", "correct": true, "because": "Linearer Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Entwurf arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "System entwerfen ist Schritt"}, {"text": "Ja", "correct": false, "because": "Strukturierter Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase wähle ich, um die Architektur zu planen?', 3, '[{"text": "System entwerfen", "correct": true, "because": "Gesamtsystem definieren"}, {"text": "Code implementieren", "correct": false, "because": "Umsetzung"}, {"text": "Produkt warten", "correct": false, "because": "Pflegephase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sichern die Qualität?', 5, '[{"text": "Tests durchführen", "correct": true, "because": "Fehler finden"}, {"text": "Produkt warten", "correct": true, "because": "Langfristige Stabilität"}, {"text": "Ungeprüfte Entwicklung", "correct": false, "because": "Tests essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Anforderungen sind der Start. b) Wartung ist unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung zählt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "System entwerfen", "correct": false, "because": "Architektur planen"}, {"text": "Tests durchführen", "correct": false, "because": "Qualität sichern"}, {"text": "Iterative Anpassung", "correct": true, "because": "Linearer Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Implementiere ich hier ohne Tests?', 2, '[{"text": "Nein", "correct": true, "because": "Tests durchführen folgt"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen fördern die Entwicklung?', 4, '[{"text": "Anforderungen festlegen", "correct": true, "because": "Basis schaffen"}, {"text": "Code implementieren", "correct": true, "because": "Umsetzung"}, {"text": "Zufällige Änderungen", "correct": false, "because": "Linearer Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Wartung fertig bin. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Produkt warten ist Schritt"}, {"text": "Ja", "correct": false, "because": "Langfristige Pflege"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich nach dem Entwurf?', 3, '[{"text": "Code implementieren", "correct": true, "because": "Umsetzung starten"}, {"text": "Tests durchführen", "correct": false, "because": "Nach Implementierung"}, {"text": "Produkt warten", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Systementwurf kommt vor Implementierung. b) Tests sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Klarheit", "correct": true, "because": "Linearer Prozess"}, {"text": "Qualitätssicherung", "correct": true, "because": "Tests durchführen"}, {"text": "Flexible Änderungen", "correct": false, "because": "Strukturierter Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Anforderungen festlegen", "correct": false, "because": "Grundlage"}, {"text": "Code implementieren", "correct": false, "because": "Umsetzung"}, {"text": "Iterative Zyklen", "correct": true, "because": "Linearer Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Wartung hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Produkt warten ist Phase"}, {"text": "Ja", "correct": false, "because": "Langfristige Pflege"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Tests arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Tests durchführen ist Schritt"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach der Implementierung?', 4, '[{"text": "Tests durchführen", "correct": true, "because": "Qualität prüfen"}, {"text": "System entwerfen", "correct": false, "because": "Vor Implementierung"}, {"text": "Anforderungen festlegen", "correct": false, "because": "Erster Schritt"}]');
